	folded := []byte(host)
	for i, c := range folded {
		switch {
		case c >= 0x80:
			return ""
		case 'A' <= c && c <= 'Z':
			folded[i] = c + ('a' - 'A')
		}
	}
	if zone != "" {
		zone = "%" + zone
	}
